(async () => {
  try {
    const fs = require('node:fs');
    const path = require('node:path');
    const { pathToFileURL } = require('node:url');
    const { spawnSync } = require('node:child_process');
    const env = {
      PATH: process.env.PATH || '/usr/bin:/bin', LANG: 'C.UTF-8', TZ: 'Europe/Zurich',
      GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
      GIT_TERMINAL_PROMPT: '0'
    };
    const git = args => {
      const result = spawnSync('git', ['--no-optional-locks', '-C', process.cwd(),
        '-c', 'core.fsmonitor=false', ...args],
        { env, encoding: 'utf8', timeout: 3000, maxBuffer: 4096, windowsHide: true });
      if (result.error || result.status !== 0 || result.signal || typeof result.stdout !== 'string') throw Error();
      const value = result.stdout.replace(/\r?\n$/, '');
      if (!value || /[\r\n\0]/.test(value)) throw Error();
      return value;
    };
    const root = fs.realpathSync(git(['rev-parse', '--show-toplevel']));
    const origin = git(['config', '--local', '--get', 'remote.origin.url']);
    if (!/^(?:https:\/\/github\.com\/|git@github\.com:|ssh:\/\/git@github\.com\/)allengchour-glitch\/aban-news-landing(?:\.git)?\/?$/i.test(origin)) throw Error();
    const directory = path.join(root, 'automation');
    const target = path.join(directory, 'claude-assist.mjs');
    const parent = fs.lstatSync(directory), script = fs.lstatSync(target);
    if (!parent.isDirectory() || parent.isSymbolicLink() || !script.isFile() || script.isSymbolicLink()) throw Error();
    process.argv = [process.execPath, target, 'mcp'];
    await import(pathToFileURL(target).href);
  } catch {
    process.stderr.write('LuxeStyle Assist konnte nicht sicher gestartet werden.\n');
    process.exitCode = 1;
  }
})();

(async () => {
  try {
    const fs = require('node:fs');
    const path = require('node:path');
    const { createHash } = require('node:crypto');
    const { spawn, spawnSync } = require('node:child_process');
    const gitEnv = {
      PATH: process.env.PATH || '/usr/bin:/bin', LANG: 'C.UTF-8', TZ: 'Europe/Zurich',
      GIT_CONFIG_NOSYSTEM: '1', GIT_CONFIG_GLOBAL: process.platform === 'win32' ? 'NUL' : '/dev/null',
      GIT_TERMINAL_PROMPT: '0'
    };
    const git = args => {
      const result = spawnSync('git', ['--no-optional-locks', '-C', process.cwd(),
        '-c', 'core.fsmonitor=false', ...args],
        { env: gitEnv, encoding: 'utf8', timeout: 3000, maxBuffer: 4096, windowsHide: true });
      if (result.error || result.status !== 0 || result.signal || typeof result.stdout !== 'string') throw Error();
      const value = result.stdout.replace(/\r?\n$/, '');
      if (!value || /[\r\n\0]/.test(value)) throw Error();
      return value;
    };
    const root = fs.realpathSync(git(['rev-parse', '--show-toplevel']));
    const origin = git(['config', '--local', '--get', 'remote.origin.url']);
    if (!/^(?:https:\/\/github\.com\/|git@github\.com:|ssh:\/\/git@github\.com\/)allengchour-glitch\/aban-news-landing(?:\.git)?\/?$/i.test(origin)) throw Error();
    const expected = new Map([
      ['automation/cj-read-mcp.mjs', 'ef986b11c17d707aa78208c2fd51d4b35486a86e85c2883618daa2e8f8c80ffc'],
      ['automation/lib/cj_identity.mjs', '1fef93809ba5e8cf2204203abdf3d38ee1ebedbb833167f50a78b8ad1fce024b'],
      ['automation/lib/cj_read_mcp.mjs', '593cb778745742f8818295ba8785a0902145c745cdd64751ff79786f80b94097'],
      ['automation/lib/cj_readonly.mjs', '8b114bc3fdf92a34e7aa4b72809cc57fdf7013a486068ab2496509237419a0ef'],
      ['automation/lib/claude_assist_mcp.mjs', '228be1d0783fb688e2f6971f39fd6a29457a24138bc5242de2f648345793a671']
    ]);
    for (const [relative, digest] of expected) {
      if (git(['ls-files', '--error-unmatch', relative]) !== relative) throw Error();
      const file = path.join(root, relative);
      const stat = fs.lstatSync(file);
      if (!stat.isFile() || stat.isSymbolicLink() || stat.size > 1024 * 1024
        || fs.realpathSync(file) !== file
        || createHash('sha256').update(fs.readFileSync(file)).digest('hex') !== digest) throw Error();
    }
    const target = path.join(root, 'automation/cj-read-mcp.mjs');
    const childEnv = { LANG: 'C.UTF-8', TZ: 'Europe/Zurich', NODE_OPTIONS: '', NODE_PATH: '', NODE_USE_ENV_PROXY: '1' };
    if (process.env.CJ_API_KEY !== undefined) childEnv.CJ_API_KEY = process.env.CJ_API_KEY;
    const child = spawn(process.execPath, [target], { cwd: root, env: childEnv, stdio: 'inherit', windowsHide: true });
    for (const signal of ['SIGINT', 'SIGTERM']) process.once(signal, () => child.kill(signal));
    const result = await new Promise((resolve, reject) => {
      child.once('error', reject);
      child.once('exit', (code, signal) => resolve({ code, signal }));
    });
    if (result.signal || result.code !== 0) throw Error();
  } catch {
    process.stderr.write('LuxeStyle CJ Read konnte nicht sicher gestartet werden.\n');
    process.exitCode = 1;
  }
})();
